-- Hand-written web3 lessons, days 6-30 (100 stacks: one per day and learner goal).
-- Tagged handwritten-v1, so Days 1-30 pick them over older generated stacks (mobile/lib/handwritten.ts).
-- Safe to run more than once: stacks upsert on id, and each stack's slides are replaced.
BEGIN;
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tags = EXCLUDED.tags, stack_type = EXCLUDED.stack_type,
  authored_lesson = EXCLUDED.authored_lesson, duration_minutes = EXCLUDED.duration_minutes,
  published_at = COALESCE(stacks.published_at, EXCLUDED.published_at);

